#!/usr/bin/env node
/**
 * Generate static/admin/config.yml + _category_.json files from the folder tree.
 * The folder structure is the single source of truth: one i18n CMS collection
 * per folder (so every folder, incl. newly created nested ones, is editable),
 * plus a "free path" collection to create pages in arbitrary/new nested folders.
 * _category_.json gives known folders nice labels + order in the (autogenerated)
 * sidebar; unknown (new) folders fall back to their folder name.
 * Runs first in build:all.
 */
import fs from 'node:fs';
import path from 'node:path';
import yaml from 'js-yaml';
import {
  ROOT,
  NL_DOCS,
  SECTIONS,
  collName,
  folderLabel,
  allFolders,
} from './wiki-sections.mjs';

const FIELDS = [
  { label: 'Titel', name: 'title', widget: 'string', required: false, i18n: true },
  { label: 'Sidebar-label', name: 'sidebar_label', widget: 'string', required: false, i18n: true },
  { label: 'Sidebar-positie', name: 'sidebar_position', widget: 'number', required: false, value_type: 'int', min: 1, i18n: 'duplicate' },
  { label: 'Slug (URL)', name: 'slug', widget: 'string', required: false, i18n: 'duplicate' },
  { label: 'Inhoud', name: 'body', widget: 'markdown', i18n: true },
];

const collections = allFolders().map((rel) => ({
  name: collName(rel),
  label: rel ? `${folderLabel(rel)} — ${rel}` : 'Algemeen (root)',
  folder: rel ? `docs/${rel}` : 'docs',
  extension: 'md',
  format: 'frontmatter',
  create: true,
  i18n: true,
  fields: FIELDS,
}));

// NB: no "free path" collection — Sveltia slugifies the path field (so a `/`
// becomes a dash, no nesting) AND writes it as junk frontmatter. New / nested
// folders are created instead via the tree page's "Verplaats → Ander pad",
// where the move workflow keeps slashes verbatim.

const config = {
  backend: {
    name: 'github',
    repo: 'danielsand1984/yres-wiki',
    branch: 'main',
    base_url: 'https://oogopdata.nl',
    auth_endpoint: 'api/cms-auth',
    commit_messages: {
      create: 'CMS: nieuwe pagina {{slug}}',
      update: 'CMS: bewerk {{slug}}',
      delete: 'CMS: verwijder {{slug}}',
      uploadMedia: 'CMS: upload {{path}}',
      deleteMedia: 'CMS: verwijder media {{path}}',
    },
  },
  media_folder: 'static/img/uploads',
  public_folder: '/img/uploads',
  publish_mode: 'simple',
  i18n: { structure: 'multiple_root_folders', locales: ['nl', 'en'], default_locale: 'nl' },
  collections,
};

const header =
  '# GENERATED by scripts/build-cms-config.mjs — do not edit by hand.\n' +
  '# One i18n collection per folder (folder structure = single source of truth).\n\n';
const outPath = path.join(ROOT, 'static', 'admin', 'config.yml');
fs.writeFileSync(outPath, header + yaml.dump(config, { lineWidth: 0 }), 'utf8');

// _category_.json for known folders (labels + order), per locale.
for (const [rel, meta] of Object.entries(SECTIONS)) {
  for (const [lang, base] of [['nl', 'nl/docs'], ['en', 'en/docs']]) {
    const dir = path.join(ROOT, base, rel);
    if (!fs.existsSync(dir)) continue;
    const data = { label: meta[lang] || meta.nl, position: meta.position };
    fs.writeFileSync(path.join(dir, '_category_.json'), JSON.stringify(data, null, 2) + '\n', 'utf8');
  }
}

console.log(`config.yml: ${collections.length} collections; _category_.json written for known folders.`);
